1682→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1683→
1684→	// If message already ends with trailers (lines starting with key:), just append
1685→	// Otherwise, add a blank line first
1686→	lines := strings.Split(strings.TrimRight(message, "\n"), "\n")
1687→
1688→	// Check if the message already ends with a trailer paragraph.
1689→	// Git trailers must be in a separate paragraph (preceded by a blank line).
1690→	// A single-paragraph message (e.g., just a subject line) cannot have trailers,
1691→	// even if the subject contains ": " (like conventional commits: "docs: Add foo").
1692→	//
1693→	// Scan from the bottom: find the last paragraph of non-comment content,
1694→	// then check if it looks like trailers AND has a blank line above it.
1695→	hasTrailers := false
1696→	i := len(lines) - 1
1697→
1698→	// Skip trailing comment lines
1699→	for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
1700→		i--
1701→	}
1702→
1703→	// Check if the last non-comment line looks like a trailer
1704→	if i >= 0 {
1705→		line := strings.TrimSpace(lines[i])
1706→		if line != "" && strings.Contains(line, ": ") {
1707→			// Found a trailer-like line. Now scan upward past the trailer block
1708→			// to verify there's a blank line (paragraph separator) above it.
1709→			for i > 0 {
1710→				i--
1711→				above := strings.TrimSpace(lines[i])
1712→				if strings.HasPrefix(above, "#") {
1713→					continue
1714→				}
1715→				if above == "" {
1716→					// Blank line found above trailer block — real trailers
1717→					hasTrailers = true
1718→					break
1719→				}
1720→				if !strings.Contains(above, ": ") {
1721→					// Non-trailer, non-blank line — this is message body, not trailers
1722→					break
1723→				}
1724→				// Another trailer-like line, keep scanning upward
1725→			}
1726→		}
1727→	}
1728→
1729→	if hasTrailers {
1730→		// Append trailer directly
1731→		return strings.TrimRight(message, "\n") + "\n" + trailer + "\n"
1732→	}
1733→
1734→	// Add blank line before trailer
1735→	return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n"
1736→}
