391→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
392→// When force is true, it amends without prompting.
393→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
394→	// Get HEAD commit info
395→	repo, err := openRepository(ctx)
396→	if err != nil {
397→		return fmt.Errorf("failed to open repository: %w", err)
398→	}
399→	headRef, err := repo.Head()
400→	if err != nil {
401→		return fmt.Errorf("failed to get HEAD: %w", err)
402→	}
403→	headCommit, err := repo.CommitObject(headRef.Hash())
404→	if err != nil {
405→		return fmt.Errorf("failed to get HEAD commit: %w", err)
406→	}
407→
408→	shortHash := headRef.Hash().String()[:7]
409→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
410→
411→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
412→
413→	amend := true
414→	if !force {
415→		form := NewAccessibleForm(
416→			huh.NewGroup(
417→				huh.NewConfirm().
418→					Title("Amend the last commit in this branch?").
419→					Affirmative("Y").
420→					Negative("n").
421→					Value(&amend),
422→			),
423→		)
424→		if err := form.Run(); err != nil {
425→			return fmt.Errorf("prompt failed: %w", err)
426→		}
427→	}
428→
429→	if !amend {
430→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
431→		return nil
432→	}
433→
434→	// Skip amending if this exact checkpoint ID is already in the commit
435→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
436→		if existing.String() == checkpointIDStr {
437→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
438→			return nil
439→		}
440→	}
441→
442→	// Amend the commit with the checkpoint trailer.
443→	newMessage := appendCheckpointTrailer(headCommit.Message, checkpointIDStr)
444→
445→	// --only ensures this amend updates the commit message only and does not
446→	// accidentally include unrelated staged changes.
447→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
448→	if output, err := cmd.CombinedOutput(); err != nil {
449→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
450→	}
451→
452→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
453→	return nil
454→}
455→
456→// trailerLineRe matches git trailer format: "Key-Name: value" (no spaces before colon).
457→var trailerLineRe = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9-]*: `)
458→
459→// isTrailerLine reports whether a line matches git trailer format.
460→func isTrailerLine(line string) bool {
461→	return trailerLineRe.MatchString(line)
462→}
463→
464→// appendCheckpointTrailer appends Entire-Checkpoint in trailer-aware format.
465→// If the message already ends with a trailer paragraph, append directly to it;
466→// otherwise add a blank line before starting a new trailer block.
467→func appendCheckpointTrailer(message, checkpointID string) string {
468→	trimmed := strings.TrimRight(message, "\n")
469→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointID)
470→
471→	lines := strings.Split(trimmed, "\n")
472→	i := len(lines) - 1
473→	for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
474→		i--
475→	}
476→
477→	hasTrailerBlock := false
478→	if i >= 0 {
479→		last := strings.TrimSpace(lines[i])
480→		if last != "" && isTrailerLine(last) {
481→			for i > 0 {
482→				i--
483→				above := strings.TrimSpace(lines[i])
484→				if strings.HasPrefix(above, "#") {
485→					continue
486→				}
487→				if above == "" {
488→					hasTrailerBlock = true
489→					break
490→				}
491→				if !isTrailerLine(above) {
492→					break
493→				}
494→			}
495→		}
496→	}
497→
498→	if hasTrailerBlock {
499→		return trimmed + "\n" + trailer + "\n"
500→	}
501→	return trimmed + "\n\n" + trailer + "\n"
502→}
503→
504→// transcriptMetadata holds metadata extracted from a single transcript parse pass.
505→type transcriptMetadata struct {
506→	FirstPrompt string
507→	TurnCount   int
508→	Model       string
509→}
510→
511→// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
512→// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
513→// Gemini JSON format.
514→func extractTranscriptMetadata(data []byte) transcriptMetadata {
515→	var meta transcriptMetadata
516→
517→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
518→	lines, err := transcript.ParseFromBytes(data)
519→	if err == nil {
520→		for _, line := range lines {
521→			if line.Type == transcript.TypeUser {
522→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
523→					meta.TurnCount++
524→					if meta.FirstPrompt == "" {
525→						meta.FirstPrompt = prompt
526→					}
527→				}
528→			}
529→			if line.Type == transcript.TypeAssistant && meta.Model == "" {
530→				var msg struct {
531→					Model string `json:"model"`
532→				}
533→				if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
534→					meta.Model = msg.Model
535→				}
536→			}
537→		}
538→		if meta.TurnCount > 0 || meta.Model != "" {
539→			return meta
540→		}
541→	}
542→
543→	// Fallback: try Gemini JSON format {"messages": [...]}
544→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
545→		meta.FirstPrompt = prompts[0]
546→		meta.TurnCount = len(prompts)
547→	}
548→
549→	return meta
550→}
551→
552→// normalizeGeminiTranscript normalizes user message content fields in-place from
553→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
554→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
555→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
556→	var raw map[string]json.RawMessage
557→	if err := json.Unmarshal(data, &raw); err != nil {
558→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
559→	}
560→
561→	messagesRaw, ok := raw["messages"]
562→	if !ok {
563→		return data, nil
564→	}
565→
566→	var messages []json.RawMessage
567→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
568→		return nil, fmt.Errorf("failed to parse messages: %w", err)
569→	}
570→
571→	changed := false
572→	for i, msgRaw := range messages {
573→		var msg map[string]json.RawMessage
574→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
575→			continue
576→		}
577→
578→		contentRaw, hasContent := msg["content"]
579→		if !hasContent || len(contentRaw) == 0 {
580→			continue
581→		}
582→
583→		// Skip if already a string
584→		var strContent string
585→		if json.Unmarshal(contentRaw, &strContent) == nil {
586→			continue
587→		}
588→
589→		// Try to convert array of {"text":"..."} to a plain string
590→		var parts []struct {
591→			Text string `json:"text"`
592→		}
593→		if json.Unmarshal(contentRaw, &parts) != nil {
594→			continue
595→		}
596→
597→		var texts []string
598→		for _, p := range parts {
599→			if p.Text != "" {
600→				texts = append(texts, p.Text)
601→			}
602→		}
603→		joined := strings.Join(texts, "\n")
604→		strBytes, err := json.Marshal(joined)
605→		if err != nil {
606→			continue
607→		}
608→		msg["content"] = strBytes
609→		rewritten, err := json.Marshal(msg)
610→		if err != nil {
611→			continue
612→		}
613→		messages[i] = rewritten
614→		changed = true
615→	}
616→
617→	if !changed {
618→		return data, nil
619→	}
620→
621→	rewrittenMessages, err := json.Marshal(messages)
622→	if err != nil {
623→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
624→	}
625→	raw["messages"] = rewrittenMessages
626→
627→	result, err := json.MarshalIndent(raw, "", "  ")
628→	if err != nil {
629→		return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
630→	}
631→	return result, nil
632→}
633→
634→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
635→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
636→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
637→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
638→func estimateSessionDuration(data []byte) int64 {
639→	type timestamped struct {
640→		Timestamp string `json:"timestamp"`
641→	}
642→
643→	var first, last time.Time
644→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
645→		if len(rawLine) == 0 {
646→			continue
647→		}
648→		var ts timestamped
649→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
650→			continue
651→		}
652→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
653→		if err != nil {
654→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
655→			if err != nil {
656→				continue
657→			}
658→		}
659→		if first.IsZero() {
660→			first = parsed
661→		}
662→		last = parsed
663→	}
664→
665→	if first.IsZero() || last.IsZero() || !last.After(first) {
666→		return 0
667→	}
668→	return last.Sub(first).Milliseconds()
669→}
