content.content:
  1→// Package claudecode implements the Agent interface for Claude Code.
  2→package claudecode
  3→
  4→import (
  5→	"bufio"
  6→	"context"
  7→	"encoding/json"
  8→	"errors"
  9→	"fmt"
 10→	"io"
 11→	"os"
 12→	"path/filepath"
 13→	"regexp"
 14→	"time"
 15→
 16→	"github.com/entireio/cli/cmd/entire/cli/agent"
 17→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 18→	"github.com/entireio/cli/cmd/entire/cli/paths"
 19→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 20→)
 21→
 22→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 23→func init() {
 24→	agent.Register(agent.AgentNameClaudeCode, NewClaudeCodeAgent)
 25→}
 26→
 27→// ClaudeCodeAgent implements the Agent interface for Claude Code.
 28→//
 29→//nolint:revive // ClaudeCodeAgent is clearer than Agent in this context
 30→type ClaudeCodeAgent struct{}
 31→
 32→// NewClaudeCodeAgent creates a new Claude Code agent instance.
 33→func NewClaudeCodeAgent() agent.Agent {
 34→	return &ClaudeCodeAgent{}
 35→}
 36→
 37→// Name returns the agent registry key.
 38→func (c *ClaudeCodeAgent) Name() types.AgentName {
 39→	return agent.AgentNameClaudeCode
 40→}
 41→
 42→// Type returns the agent type identifier.
 43→func (c *ClaudeCodeAgent) Type() types.AgentType {
 44→	return agent.AgentTypeClaudeCode
 45→}
 46→
 47→// Description returns a human-readable description.
 48→func (c *ClaudeCodeAgent) Description() string {
 49→	return "Claude Code - Anthropic's CLI coding assistant"
 50→}
 51→
 52→func (c *ClaudeCodeAgent) IsPreview() bool { return false }
 53→
 54→// DetectPresence checks if Claude Code is configured in the repository.
 55→func (c *ClaudeCodeAgent) DetectPresence(ctx context.Context) (bool, error) {
 56→	// Get worktree root to check for .claude directory
 57→	// This is needed because the CLI may be run from a subdirectory
 58→	repoRoot, err := paths.WorktreeRoot(ctx)
 59→	if err != nil {
 60→		// Not in a git repo, fall back to CWD-relative check
 61→		repoRoot = "."
 62→	}
 63→
 64→	// Check for .claude directory
 65→	claudeDir := filepath.Join(repoRoot, ".claude")
 66→	if _, err := os.Stat(claudeDir); err == nil {
 67→		return true, nil
 68→	}
 69→	// Check for .claude/settings.json
 70→	settingsFile := filepath.Join(repoRoot, ".claude", "settings.json")
 71→	if _, err := os.Stat(settingsFile); err == nil {
 72→		return true, nil
 73→	}
 74→	return false, nil
 75→}
 76→
 77→// GetSessionID extracts the session ID from hook input.
 78→func (c *ClaudeCodeAgent) GetSessionID(input *agent.HookInput) string {
 79→	return input.SessionID
 80→}
 81→
 82→// ResolveSessionFile returns the path to a Claude session file.
 83→// Claude names files directly as <id>.jsonl.
 84→func (c *ClaudeCodeAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 85→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 86→}
 87→
 88→// ProtectedDirs returns directories that Claude uses for config/state.
 89→func (c *ClaudeCodeAgent) ProtectedDirs() []string { return []string{".claude"} }
 90→
 91→// GetSessionDir returns the directory where Claude stores session transcripts.
 92→func (c *ClaudeCodeAgent) GetSessionDir(repoPath string) (string, error) {
 93→	// Check for test environment override
 94→	if override := os.Getenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR"); override != "" {
 95→		return override, nil
 96→	}
 97→
 98→	homeDir, err := os.UserHomeDir()
 99→	if err != nil {
100→		return "", fmt.Errorf("failed to get home directory: %w", err)
101→	}
102→
103→	projectDir := SanitizePathForClaude(repoPath)
104→	return filepath.Join(homeDir, ".claude", "projects", projectDir), nil
105→}
106→
107→// ReadSession reads a session from Claude's storage (JSONL transcript file).
108→// The session data is stored in NativeData as raw JSONL bytes.
109→// ModifiedFiles is computed by parsing the transcript.
110→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	// Read the raw JSONL file
116→	data, err := os.ReadFile(input.SessionRef)
117→	if err != nil {
118→		return nil, fmt.Errorf("failed to read transcript: %w", err)
119→	}
120→
121→	// Parse to extract computed fields
122→	lines, err := transcript.ParseFromBytes(data)
123→	if err != nil {
124→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
125→	}
126→
127→	return &agent.AgentSession{
128→		SessionID:     input.SessionID,
129→		AgentName:     c.Name(),
130→		SessionRef:    input.SessionRef,
131→		StartTime:     time.Now(),
132→		NativeData:    data,
133→		ModifiedFiles: ExtractModifiedFiles(lines),
134→	}, nil
135→}
