388→		"calculate-total-tokens", "--offset", strconv.Itoa(fromOffset), "--subagents-dir", subagentsDir)
389→	if err != nil {
390→		return nil, fmt.Errorf("calculate-total-tokens: %w", err)
391→	}
392→	var resp TokenUsageResponse
393→	if err := json.Unmarshal(stdout, &resp); err != nil {
394→		return nil, fmt.Errorf("calculate-total-tokens: invalid JSON: %w", err)
395→	}
396→	return convertTokenUsage(&resp), nil
397→}
