108→// AgentTranscriptPath returns the path to a subagent's transcript file.
109→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
110→// as the main transcript.
111→func AgentTranscriptPath(transcriptDir, agentID string) string {
112→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
113→}
