115→// toolResultBlock represents a tool_result in a user message
116→type toolResultBlock struct {
117→	Type      string `json:"type"`
118→	ToolUseID string `json:"tool_use_id"`
119→}
120→
121→// userMessageWithToolResults represents a user message that may contain tool results
122→type userMessageWithToolResults struct {
123→	Content []toolResultBlock `json:"content"`
124→}
125→
126→// FindCheckpointUUID finds the UUID of the message containing the tool_result
127→// for the given tool_use_id. This is used to find the checkpoint point for
128→// transcript truncation when rewinding to a task.
129→// Returns the UUID and true if found, empty string and false otherwise.
130→func FindCheckpointUUID(lines []transcriptLine, toolUseID string) (string, bool) {
131→	for _, line := range lines {
132→		if line.Type != transcript.TypeUser {
133→			continue
134→		}
135→
136→		var msg userMessageWithToolResults
137→		if err := json.Unmarshal(line.Message, &msg); err != nil {
138→			continue
139→		}
140→
141→		for _, block := range msg.Content {
142→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
143→				return line.UUID, true
144→			}
145→		}
146→	}
147→	return "", false
148→}
149→
150→// TruncateTranscriptAtUUID returns transcript lines up to and including the
151→// line with the given UUID. If the UUID is not found or is empty, returns
152→// the entire transcript.
153→//
154→//nolint:revive // Exported for testing purposes
155→func TruncateTranscriptAtUUID(lines []transcriptLine, uuid string) []transcriptLine {
156→	if uuid == "" {
157→		return lines
158→	}
159→
160→	for i, line := range lines {
161→		if line.UUID == uuid {
162→			return lines[:i+1]
163→		}
164→	}
165→
166→	// UUID not found, return full transcript
167→	return lines
168→}
169→
170→// writeTranscript writes transcript lines to a file in JSONL format.
171→func writeTranscript(path string, lines []transcriptLine) error {
172→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
173→	if err != nil {
174→		return fmt.Errorf("failed to create file: %w", err)
175→	}
176→	defer func() { _ = file.Close() }()
177→
178→	for _, line := range lines {
179→		data, err := json.Marshal(line)
180→		if err != nil {
181→			return fmt.Errorf("failed to marshal line: %w", err)
182→		}
183→		if _, err := file.Write(data); err != nil {
184→			return fmt.Errorf("failed to write line: %w", err)
185→		}
186→		if _, err := file.WriteString("\n"); err != nil {
187→			return fmt.Errorf("failed to write newline: %w", err)
188→		}
189→	}
190→
191→	return nil
192→}
193→
194→// TranscriptPosition contains the position information for a transcript file.
195→type TranscriptPosition struct {
196→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
197→	LineCount int    // Total number of lines
198→}
199→
200→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
201→// Returns empty position if file doesn't exist or is empty.
202→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
203→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
204→	if path == "" {
205→		return TranscriptPosition{}, nil
206→	}
207→
208→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
209→	if err != nil {
210→		if os.IsNotExist(err) {
211→			return TranscriptPosition{}, nil
212→		}
213→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
214→	}
215→	defer func() { _ = file.Close() }()
216→
217→	var pos TranscriptPosition
218→	reader := bufio.NewReader(file)
219→
220→	for {
221→		lineBytes, err := reader.ReadBytes('\n')
222→		if err != nil && err != io.EOF {
223→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
224→		}
225→
226→		if len(lineBytes) == 0 {
227→			if err == io.EOF {
228→				break
229→			}
230→			continue
231→		}
232→
233→		pos.LineCount++
234→
235→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
236→		var line transcriptLine
237→		if err := json.Unmarshal(lineBytes, &line); err == nil {
238→			if line.UUID != "" {
239→				pos.LastUUID = line.UUID
240→			}
241→		}
242→
243→		if err == io.EOF {
244→			break
245→		}
246→	}
247→
248→	return pos, nil
249→}
