		if last != "" && isTrailerLine(last) {
			for i > 0 {
				i--
				above := strings.TrimSpace(lines[i])
				if strings.HasPrefix(above, "#") {
					continue
				}
				if above == "" {
					hasTrailerBlock = true
					break
				}
				if !isTrailerLine(above) {
					break
				}
			}
		}
	}

	if hasTrailerBlock {
		return trimmed + "\n" + trailer + "\n"
	}
	return trimmed + "\n\n" + trailer + "\n"
}

