			data: `{"messages": [
				{"id": "msg-1", "type": "user", "content": "hello"},
				{"type": "gemini", "content": "hi"}
			]}`,
			want:    "",
			wantErr: false,
		},
		{
			name:    "invalid JSON",
			data:    `not valid json`,
			want:    "",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := GetLastMessageID([]byte(tt.data))
			if (err != nil) != tt.wantErr {
