 146→+// NormalizeTranscript normalizes user message content fields in-place from
 147→+// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
 148→+// (timestamps, thoughts, tokens, model, toolCalls, etc.).
 149→+func NormalizeTranscript(data []byte) ([]byte, error) {
 150→+	var raw map[string]json.RawMessage
 151→+	if err := json.Unmarshal(data, &raw); err != nil {
 152→+		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 153→+	}
 154→+
 155→+	messagesRaw, ok := raw["messages"]
 156→+	if !ok {
 157→+		return data, nil
 158→+	}
 159→+
 160→+	var messages []json.RawMessage
 161→+	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
 162→+		return nil, fmt.Errorf("failed to parse messages: %w", err)
 163→+	}
 164→+
 165→+	changed := false
 166→+	for i, msgRaw := range messages {
 167→+		var msg map[string]json.RawMessage
 168→+		if err := json.Unmarshal(msgRaw, &msg); err != nil {
 169→+			continue
 170→+		}
 171→+
 172→+		contentRaw, hasContent := msg["content"]
 173→+		if !hasContent || len(contentRaw) == 0 {
 174→+			continue
 175→+		}
 176→+
 177→+		// Skip if already a string
 178→+		var strContent string
 179→+		if json.Unmarshal(contentRaw, &strContent) == nil {
 180→+			continue
 181→+		}
 182→+
 183→+		// Try to convert array of {"text":"..."} to a plain string
 184→+		var parts []struct {
 185→+			Text string `json:"text"`
 186→+		}
 187→+		if json.Unmarshal(contentRaw, &parts) != nil {
 188→+			continue
 189→+		}
 190→+
 191→+		var texts []string
 192→+		for _, p := range parts {
 193→+			if p.Text != "" {
 194→+				texts = append(texts, p.Text)
 195→+			}
 196→+		}
 197→+		joined := strings.Join(texts, "\n")
 198→+		strBytes, err := json.Marshal(joined)
 199→+		if err != nil {
 200→+			continue
 201→+		}
 202→+		msg["content"] = strBytes
 203→+		rewritten, err := json.Marshal(msg)
 204→+		if err != nil {
 205→+			continue
 206→+		}
 207→+		messages[i] = rewritten
 208→+		changed = true
 209→+	}
 210→+
 211→+	if !changed {
 212→+		return data, nil
 213→+	}
 214→+
 215→+	rewrittenMessages, err := json.Marshal(messages)
 216→+	if err != nil {
 217→+		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
 218→+	}
 219→+	raw["messages"] = rewrittenMessages
 220→+
 221→+	result, err := json.MarshalIndent(raw, "", "  ")
 222→+	if err != nil {
 223→+		return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
 224→+	}
 225→+	return result, nil
 226→+}
