1738→// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
1739→// The trailer is placed above the git comment block but below the user's message area,
1740→// with a comment explaining that the user can remove it if they don't want to link the commit
1741→// to the agent session. If prompt is non-empty, it's shown as context.
1742→func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt string) string {
1743→	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
1744→	commentLines := []string{
1745→		"# Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
1746→	}
1747→	if prompt != "" {
1748→		commentLines = append(commentLines, "# Last Prompt: "+prompt)
1749→	}
1750→	commentLines = append(commentLines, "# The trailer will be added to your next commit based on this branch.")
1751→	comment := strings.Join(commentLines, "\n")
1752→
1753→	lines := strings.Split(message, "\n")
1754→
1755→	// Find where the git comment block starts (first # line)
1756→	commentStart := -1
1757→	for i, line := range lines {
1758→		if strings.HasPrefix(line, "#") {
1759→			commentStart = i
1760→			break
1761→		}
1762→	}
1763→
1764→	if commentStart == -1 {
1765→		// No git comments, append trailer at the end
1766→		return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
1767→	}
1768→
1769→	// Split into user content and git comments
1770→	userContent := strings.Join(lines[:commentStart], "\n")
1771→	gitComments := strings.Join(lines[commentStart:], "\n")
1772→
1773→	// Build result: user content, blank line, trailer, comment, blank line, git comments
1774→	userContent = strings.TrimRight(userContent, "\n")
1775→	if userContent == "" {
1776→		// No user content yet - leave space for them to type, then trailer
1777→		// Two newlines: first for user's message line, second for blank separator
1778→		return "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments

