 20→// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
 21→// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
 22→// Gemini JSON format.
 23→func extractTranscriptMetadata(data []byte) transcriptMetadata {
 24→	var meta transcriptMetadata
 25→
 26→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
 27→	lines, err := transcript.ParseFromBytes(data)
 28→	if err == nil {
 29→		for _, line := range lines {
 30→			if line.Type == transcript.TypeUser {
 31→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
 32→					meta.TurnCount++
 33→					if meta.FirstPrompt == "" {
 34→						meta.FirstPrompt = prompt
 35→					}
 36→				}
 37→			}
 38→			if line.Type == transcript.TypeAssistant && meta.Model == "" {
 39→				var msg struct {
 40→					Model string `json:"model"`
 41→				}
 42→				if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
 43→					meta.Model = msg.Model
 44→				}
 45→			}
 46→		}
 47→		if meta.TurnCount > 0 || meta.Model != "" {
 48→			return meta
 49→		}
 50→	}
 51→
 52→	// Fallback: try Gemini JSON format {"messages": [...]}
 53→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
 54→		meta.FirstPrompt = prompts[0]
 55→		meta.TurnCount = len(prompts)
 56→	}
 57→
 58→	return meta
 59→}
