 61→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
 62→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
 63→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
 64→// Uses bufio.Scanner for memory efficiency with large transcripts.
 65→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
 66→func estimateSessionDuration(data []byte) int64 {
 67→	type timestamped struct {
 68→		Timestamp string `json:"timestamp"`
 69→	}
 70→
 71→	var first, last time.Time
 72→	scanner := bufio.NewScanner(bytes.NewReader(data))
 73→	for scanner.Scan() {
 74→		rawLine := scanner.Bytes()
 75→		if len(rawLine) == 0 {
 76→			continue
 77→		}
 78→		var ts timestamped
 79→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
 80→			continue
 81→		}
 82→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
 83→		if err != nil {
 84→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
 85→			if err != nil {
 86→				continue
 87→			}
 88→		}
 89→		if first.IsZero() {
 90→			first = parsed
 91→		}
 92→		last = parsed
 93→	}
 94→
 95→	if first.IsZero() || last.IsZero() || !last.After(first) {
 96→		return 0
 97→	}
 98→	return last.Sub(first).Milliseconds()
 99→}
