260→// printAttachConfirmation prints the post-attach status message.
261→func printAttachConfirmation(w io.Writer, sessionID string, totalChanges int, fileDetectionFailed bool, condenseErr error) {
262→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
263→	switch {
264→	case totalChanges > 0:
265→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
266→	case fileDetectionFailed:
267→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, file change detection failed)")
268→	default:
269→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
270→	}
271→	if condenseErr != nil {
272→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
273→	}
274→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
275→}
