310→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
311→// Returns the checkpoint ID string and any condensation error.
312→// Note: accepts *strategy.ManualCommitStrategy directly because CondenseSessionByID is intentionally
313→// not on the Strategy interface — it's a strategy-specific repair/attach operation.
314→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
315→	var checkpointIDStr string
316→	var condenseErr error
317→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
318→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
319→		condenseErr = err
320→	}
321→
322→	// Single load serves both checkpoint ID extraction and finalization
323→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
324→	if loadErr != nil {
325→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
326→		return checkpointIDStr, condenseErr
327→	}
328→	if state == nil {
329→		return checkpointIDStr, condenseErr
330→	}
331→
332→	if condenseErr == nil {
333→		checkpointIDStr = state.LastCheckpointID.String()
334→	}
335→
336→	now := time.Now()
337→	state.LastInteractionTime = &now
338→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
339→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
340→	}
341→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
342→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
343→	}
344→
345→	return checkpointIDStr, condenseErr
346→}
