396→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
397→// When force is true, it amends without prompting.
398→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
399→	// Get HEAD commit info
400→	repo, err := openRepository(ctx)
401→	if err != nil {
402→		return fmt.Errorf("failed to open repository: %w", err)
403→	}
404→	headRef, err := repo.Head()
405→	if err != nil {
406→		return fmt.Errorf("failed to get HEAD: %w", err)
407→	}
408→	headCommit, err := repo.CommitObject(headRef.Hash())
409→	if err != nil {
410→		return fmt.Errorf("failed to get HEAD commit: %w", err)
411→	}
412→
413→	shortHash := headRef.Hash().String()[:7]
414→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
415→
416→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
417→
418→	amend := true
419→	if !force {
420→		form := NewAccessibleForm(
421→			huh.NewGroup(
422→				huh.NewConfirm().
423→					Title("Amend the last commit in this branch?").
424→					Affirmative("Y").
425→					Negative("n").
426→					Value(&amend),
427→			),
428→		)
429→		if err := form.Run(); err != nil {
430→			return fmt.Errorf("prompt failed: %w", err)
431→		}
432→	}
433→
434→	if !amend {
435→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
436→		return nil
437→	}
438→
439→	// Skip amending if this exact checkpoint ID is already in the commit
440→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
441→		if existing.String() == checkpointIDStr {
442→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
443→			return nil
444→		}
445→	}
446→
447→	// Amend the commit with the checkpoint trailer.
448→	newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
449→
450→	// --only ensures this amend updates the commit message only and does not
451→	// accidentally include unrelated staged changes.
452→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
453→	if output, err := cmd.CombinedOutput(); err != nil {
454→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
455→	}
456→
457→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
458→	return nil
459→}
