216→// NormalizeTranscript normalizes user message content fields in-place from
217→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
218→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
219→func NormalizeTranscript(data []byte) ([]byte, error) {
220→	var raw map[string]json.RawMessage
221→	if err := json.Unmarshal(data, &raw); err != nil {
222→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
223→	}
224→
225→	messagesRaw, ok := raw["messages"]
226→	if !ok {
227→		return data, nil
228→	}
229→
230→	var messages []json.RawMessage
231→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
232→		return nil, fmt.Errorf("failed to parse messages: %w", err)
233→	}
234→
235→	changed := false
236→	for i, msgRaw := range messages {
237→		var msg map[string]json.RawMessage
238→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
239→			continue
240→		}
241→
242→		contentRaw, hasContent := msg["content"]
243→		if !hasContent || len(contentRaw) == 0 {
244→			continue
245→		}
246→
247→		// Skip if already a string
248→		var strContent string
249→		if json.Unmarshal(contentRaw, &strContent) == nil {
250→			continue
251→		}
252→
253→		// Try to convert array of {"text":"..."} to a plain string
254→		var parts []struct {
255→			Text string `json:"text"`
256→		}
257→		if json.Unmarshal(contentRaw, &parts) != nil {
258→			continue
259→		}
260→
261→		var texts []string
262→		for _, p := range parts {
263→			if p.Text != "" {
264→				texts = append(texts, p.Text)
265→			}
266→		}
267→		joined := strings.Join(texts, "\n")
268→		strBytes, err := json.Marshal(joined)
269→		if err != nil {
270→			continue
271→		}
272→		msg["content"] = strBytes
273→		rewritten, err := json.Marshal(msg)
274→		if err != nil {
275→			continue
276→		}
277→		messages[i] = rewritten
278→		changed = true
279→	}
280→
281→	if !changed {
282→		return data, nil
283→	}
284→
285→	rewrittenMessages, err := json.Marshal(messages)
286→	if err != nil {
287→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
288→	}
289→	raw["messages"] = rewrittenMessages
290→
291→	result, err := json.MarshalIndent(raw, "", "  ")
292→	if err != nil {
293→		return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
294→	}
295→	return result, nil
296→}
297→
298→// SliceFromMessage returns a Gemini transcript scoped to messages starting from
299→// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
300→// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
301→// Returns the original data if startMessageIndex <= 0.
302→// Returns nil, nil if startMessageIndex exceeds the number of messages.
303→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
304→	if len(data) == 0 || startMessageIndex <= 0 {
305→		return data, nil
306→	}
307→
308→	t, err := ParseTranscript(data)
309→	if err != nil {
310→		return nil, fmt.Errorf("failed to parse transcript for slicing: %w", err)
311→	}
312→
313→	if startMessageIndex >= len(t.Messages) {
314→		return nil, nil
315→	}
316→
317→	scoped := &GeminiTranscript{
318→		Messages: t.Messages[startMessageIndex:],
319→	}
320→
321→	out, err := json.Marshal(scoped)
322→	if err != nil {
323→		return nil, fmt.Errorf("failed to marshal scoped transcript: %w", err)
324→	}
325→	return out, nil
326→}
