137→// ReadSession reads a session from Gemini's storage (JSON transcript file).
138→// The session data is stored in NativeData as raw JSON bytes.
139→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
140→	if input.SessionRef == "" {
141→		return nil, errors.New("session reference (transcript path) is required")
142→	}
143→
144→	// Read the raw JSON file
145→	data, err := os.ReadFile(input.SessionRef)
146→	if err != nil {
147→		return nil, fmt.Errorf("failed to read transcript: %w", err)
148→	}
149→
150→	// Parse to extract computed fields
151→	modifiedFiles, err := ExtractModifiedFiles(data)
152→	if err != nil {
153→		// Non-fatal: we can still return the session without modified files
154→		modifiedFiles = nil
155→	}
156→
157→	return &agent.AgentSession{
158→		SessionID:     input.SessionID,
159→		AgentName:     g.Name(),
160→		SessionRef:    input.SessionRef,
161→		StartTime:     time.Now(),
162→		NativeData:    data,
163→		ModifiedFiles: modifiedFiles,
164→	}, nil
165→}
