167→// WriteSession writes a session to Gemini's storage (JSON transcript file).
168→// Uses the NativeData field which contains raw JSON bytes.
169→func (g *GeminiCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
170→	if session == nil {
171→		return errors.New("session is nil")
172→	}
173→
174→	// Verify this session belongs to Gemini CLI
175→	if session.AgentName != "" && session.AgentName != g.Name() {
176→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
177→	}
178→
179→	if session.SessionRef == "" {
180→		return errors.New("session reference (transcript path) is required")
181→	}
182→
183→	if len(session.NativeData) == 0 {
184→		return errors.New("session has no native data to write")
185→	}
186→
187→	// Write the raw JSON data
188→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
189→		return fmt.Errorf("failed to write transcript: %w", err)
190→	}
191→
192→	return nil
193→}
