200→// GetProjectHash generates a unique hash for a project based on its root path.
201→// This matches Gemini CLI's getProjectHash() which uses SHA256 of the project root.
202→func GetProjectHash(projectRoot string) string {
203→	hash := sha256.Sum256([]byte(projectRoot))
204→	return hex.EncodeToString(hash[:])
205→}
