209→// GetTranscriptPosition returns the current message count of a Gemini transcript.
210→// Gemini uses JSON format with a messages array, so position is the message count.
211→// Returns 0 if the file doesn't exist or is empty.
212→func (g *GeminiCLIAgent) GetTranscriptPosition(path string) (int, error) {
213→	if path == "" {
214→		return 0, nil
215→	}
216→
217→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
218→	if err != nil {
219→		if os.IsNotExist(err) {
220→			return 0, nil
221→		}
222→		return 0, fmt.Errorf("failed to read transcript: %w", err)
223→	}
224→
225→	if len(data) == 0 {
226→		return 0, nil
227→	}
228→
229→	transcript, err := ParseTranscript(data)
230→	if err != nil {
231→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
232→	}
233→
234→	return len(transcript.Messages), nil
235→}
