237→// ExtractModifiedFilesFromOffset extracts files modified since a given message index.
238→// For Gemini (JSON format), offset is the starting message index.
239→// Returns:
240→//   - files: list of file paths modified by Gemini (from Write/Edit tools)
241→//   - currentPosition: total number of messages in the transcript
242→//   - error: any error encountered during reading
243→func (g *GeminiCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
244→	if path == "" {
245→		return nil, 0, nil
246→	}
247→
248→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
249→	if readErr != nil {
250→		if os.IsNotExist(readErr) {
251→			return nil, 0, nil
252→		}
253→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
254→	}
255→
256→	if len(data) == 0 {
257→		return nil, 0, nil
258→	}
259→
260→	transcript, parseErr := ParseTranscript(data)
261→	if parseErr != nil {
262→		return nil, 0, parseErr
263→	}
264→
265→	totalMessages := len(transcript.Messages)
266→
267→	// Extract files from messages starting at startOffset
268→	fileSet := make(map[string]bool)
269→	for i := startOffset; i < len(transcript.Messages); i++ {
270→		msg := transcript.Messages[i]
271→		// Only process gemini messages (assistant messages)
272→		if msg.Type != MessageTypeGemini {
273→			continue
274→		}
275→
276→		// Process tool calls in this message
277→		for _, toolCall := range msg.ToolCalls {
278→			// Check if it's a file modification tool
279→			isModifyTool := false
280→			for _, name := range FileModificationTools {
281→				if toolCall.Name == name {
282→					isModifyTool = true
283→					break
284→				}
285→			}
286→
287→			if !isModifyTool {
288→				continue
289→			}
290→
291→			// Extract file path from args map
292→			var file string
293→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
294→				file = fp
295→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
296→				file = p
297→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
298→				file = fn
299→			}
300→
301→			if file != "" && !fileSet[file] {
302→				fileSet[file] = true
303→				files = append(files, file)
304→			}
305→		}
306→	}
307→
308→	return files, totalMessages, nil
309→}
310→
311→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
312→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
313→// the messages array while preserving the JSON structure in each chunk.
314→func (g *GeminiCLIAgent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
315→	var transcript GeminiTranscript
316→	if err := json.Unmarshal(content, &transcript); err != nil {
317→		// Fall back to JSONL chunking if not valid Gemini JSON
318→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
319→		if chunkErr != nil {
320→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
321→		}
322→		return chunks, nil
323→	}
324→
325→	if len(transcript.Messages) == 0 {
326→		return [][]byte{content}, nil
327→	}
328→
329→	var chunks [][]byte
330→	var currentMessages []GeminiMessage
331→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
332→
333→	for i, msg := range transcript.Messages {
334→		// Marshal message to get its size
335→		msgBytes, err := json.Marshal(msg)
336→		if err != nil {
337→			logging.Warn(ctx, "failed to marshal Gemini message during chunking",
338→				slog.Int("message_index", i),
339→				slog.String("error", err.Error()),
340→			)
341→			continue
342→		}
343→		msgSize := len(msgBytes) + 1 // +1 for comma separator
344→
345→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
346→			// Save current chunk
347→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
348→			if err != nil {
349→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
350→			}
351→			chunks = append(chunks, chunkData)
352→
353→			// Start new chunk
354→			currentMessages = nil
355→			currentSize = len(`{"messages":[]}`)
356→		}
357→
358→		currentMessages = append(currentMessages, msg)
359→		currentSize += msgSize
360→	}
361→
362→	// Add the last chunk
363→	if len(currentMessages) > 0 {
364→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
365→		if err != nil {
366→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
367→		}
368→		chunks = append(chunks, chunkData)
369→	}
370→
371→	// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
372→	if len(chunks) == 0 {
373→		return nil, errors.New("failed to create any chunks: all messages failed to marshal")
374→	}
375→
376→	return chunks, nil
377→}
378→
379→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
380→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
381→	var allMessages []GeminiMessage
382→
383→	for _, chunk := range chunks {
384→		var transcript GeminiTranscript
385→		if err := json.Unmarshal(chunk, &transcript); err != nil {
386→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
387→		}
388→		allMessages = append(allMessages, transcript.Messages...)
389→	}
390→
391→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
392→	if err != nil {
393→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
394→	}
395→	return result, nil
396→}
