 13→// transcriptMetadata holds metadata extracted from a single transcript parse pass.
 14→type transcriptMetadata struct {
 15→	FirstPrompt string
 16→	TurnCount   int
 17→	Model       string
 18→}
 19→
 20→// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
 21→// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
 22→// Gemini JSON format.
 23→func extractTranscriptMetadata(data []byte) transcriptMetadata {
 24→	var meta transcriptMetadata
 25→
 26→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
 27→	lines, err := transcript.ParseFromBytes(data)
 28→	if err == nil {
 29→		for _, line := range lines {
 30→			if line.Type == transcript.TypeUser {
 31→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
 32→					meta.TurnCount++
 33→					if meta.FirstPrompt == "" {
 34→						meta.FirstPrompt = prompt
 35→					}
 36→				}
 37→			}
 38→			if line.Type == transcript.TypeAssistant && meta.Model == "" {
 39→				var msg struct {
 40→					Model string `json:"model"`
 41→				}
 42→				if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
 43→					meta.Model = msg.Model
 44→				}
 45→			}
 46→		}
 47→		if meta.TurnCount > 0 || meta.Model != "" {
 48→			return meta
 49→		}
 50→	}
 51→
 52→	// Fallback: try Gemini JSON format {"messages": [...]}
 53→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
 54→		meta.FirstPrompt = prompts[0]
 55→		meta.TurnCount = len(prompts)
 56→	}
 57→
 58→	return meta
 59→}
 60→
 61→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
 62→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
 63→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
 64→// Uses bufio.Scanner for memory efficiency with large transcripts.
 65→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
 66→func estimateSessionDuration(data []byte) int64 {
 67→	type timestamped struct {
 68→		Timestamp string `json:"timestamp"`
 69→	}
 70→
 71→	var first, last time.Time
 72→	scanner := bufio.NewScanner(bytes.NewReader(data))
 73→	for scanner.Scan() {
 74→		rawLine := scanner.Bytes()
 75→		if len(rawLine) == 0 {
 76→			continue
 77→		}
 78→		var ts timestamped
 79→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
 80→			continue
 81→		}
 82→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
 83→		if err != nil {
 84→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
 85→			if err != nil {
 86→				continue
 87→			}
 88→		}
 89→		if first.IsZero() {
 90→			first = parsed
 91→		}
 92→		last = parsed
 93→	}
 94→
 95→	if first.IsZero() || last.IsZero() || !last.After(first) {
 96→		return 0
 97→	}
 98→	return last.Sub(first).Milliseconds()
 99→}
