202→// collectFileChanges gathers modified, new, and deleted files from both transcript analysis and git status.
203→// Returns detectionFailed=true if file change detection errored (distinct from finding no changes).
204→func collectFileChanges(ctx, logCtx context.Context, ag agent.Agent, transcriptPath, repoRoot string) (modified, added, deleted []string, detectionFailed bool) {
205→	var transcriptFiles []string
206→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
207→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
208→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
209→			detectionFailed = true
210→		} else {
211→			transcriptFiles = files
212→		}
213→	}
214→
215→	changes, err := DetectFileChanges(ctx, nil)
216→	if err != nil {
217→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
218→		detectionFailed = true
219→	}
220→
221→	modified = FilterAndNormalizePaths(transcriptFiles, repoRoot)
222→	if changes != nil {
223→		added = FilterAndNormalizePaths(changes.New, repoRoot)
224→		deleted = FilterAndNormalizePaths(changes.Deleted, repoRoot)
225→		modified = mergeUnique(modified, FilterAndNormalizePaths(changes.Modified, repoRoot))
226→	}
227→
228→	modified = filterToUncommittedFiles(ctx, modified, repoRoot)
229→	return modified, added, deleted, detectionFailed
230→}
