348→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
349→// project directories if needed.
350→func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
351→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
352→	if err != nil {
353→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
354→	}
355→	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
356→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
357→		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
358→			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
359→		}
360→	}
361→	// Agents use cwd-derived project directories, so the transcript may be stored under
362→	// a different project directory if the session was started from a different working directory.
363→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
364→		return transcriptPath, nil
365→	}
366→	found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
367→	if searchErr == nil {
368→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
369→		return found, nil
370→	}
371→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
372→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
373→}
374→
375→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
376→// transcript resolution succeeds for the given session ID.
377→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
378→	for _, name := range agent.List() {
379→		if name == skip {
380→			continue
381→		}
382→		ag, err := agent.Get(name)
383→		if err != nil {
384→			continue
385→		}
386→		path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
387→		if resolveErr != nil {
388→			logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
389→			continue
390→		}
391→		return ag, path, nil
392→	}
393→	return nil, "", errors.New("transcript not found for any registered agent")
394→}
